import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  server: {
    port: 8000,
    host: '0.0.0.0',
    proxy: {
      '/api': {
        target: 'http://localhost:3000',
        changeOrigin: true,
      },
    },
  },
});

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';
import './index.css';

ReactDOM.createRoot(document.getElementById('root')).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, sans-serif;
  background: #0f172a;
  color: #e2e8f0;
  min-height: 100vh;
}

.app {
  max-width: 960px;
  margin: 0 auto;
  padding: 2rem 1rem;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  margin-bottom: 1.5rem;
  color: #f8fafc;
}

/* Summary cards */
.summary {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 1rem;
  margin-bottom: 2rem;
}

.card {
  background: #1e293b;
  border: 1px solid #334155;
  border-radius: 12px;
  padding: 1.25rem;
  text-align: center;
}

.card .label {
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #94a3b8;
  margin-bottom: 0.5rem;
}

.card .value {
  font-size: 1.75rem;
  font-weight: 700;
  color: #38bdf8;
}

.card .value.min { color: #4ade80; }
.card .value.max { color: #f87171; }

/* Table */
.table-wrap {
  background: #1e293b;
  border: 1px solid #334155;
  border-radius: 12px;
  overflow: hidden;
}

.table-scroll {
  max-height: 480px;
  overflow-y: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9rem;
}

thead {
  position: sticky;
  top: 0;
  z-index: 1;
}

th {
  background: #334155;
  color: #e2e8f0;
  text-align: left;
  padding: 0.75rem 1rem;
  font-weight: 600;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

td {
  padding: 0.6rem 1rem;
  border-top: 1px solid #293548;
}

tbody tr:hover {
  background: #263348;
}

.loading, .error {
  text-align: center;
  padding: 3rem;
  color: #94a3b8;
  font-size: 1.1rem;
}

.error { color: #f87171; }

import { useState, useEffect } from 'react';

export default function App() {
  const [readings, setReadings] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetch('/api/readings')
      .then((res) => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return res.json();
      })
      .then((data) => {
        setReadings(data);
        setLoading(false);
      })
      .catch((err) => {
        setError(err.message);
        setLoading(false);
      });
  }, []);

  // Summary calculations
  const count = readings.length;
  const temps = readings.map((r) => r.temperature_c);
  const minTemp = temps.length ? Math.min(...temps) : null;
  const maxTemp = temps.length ? Math.max(...temps) : null;
  const avgTemp = temps.length ? (temps.reduce((a, b) => a + b, 0) / temps.length).toFixed(1) : null;

  if (loading) return <div className="loading">Loading sensor data…</div>;
  if (error) return <div className="error">Failed to load data: {error}</div>;

  return (
    <div className="dashboard">
      <h1>🌡️ Sensor Dashboard</h1>

      {/* Summary Cards */}
      <div className="summary">
        <div className="card">
          <span className="card-label">Total Readings</span>
          <span className="card-value">{count}</span>
        </div>
        <div className="card">
          <span className="card-label">Min Temperature</span>
          <span className="card-value">{minTemp}°C</span>
        </div>
        <div className="card">
          <span className="card-label">Max Temperature</span>
          <span className="card-value">{maxTemp}°C</span>
        </div>
        <div className="card">
          <span className="card-label">Avg Temperature</span>
          <span className="card-value">{avgTemp}°C</span>
        </div>
      </div>

      {/* Readings Table */}
      <div className="table-wrap">
        <table>
          <thead>
            <tr>
              <th>#</th>
              <th>Timestamp</th>
              <th>Sensor</th>
              <th>Temperature (°C)</th>
            </tr>
          </thead>
          <tbody>
            {readings.map((r, i) => (
              <tr key={i}>
                <td>{i + 1}</td>
                <td>{r.timestamp}</td>
                <td>{r.sensor}</td>
                <td>{r.temperature_c}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
